CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "type" varchar not null default 'user', "disabled_at" datetime, "app_authentication_secret" text, "app_authentication_recovery_codes" text);
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE "personal_access_tokens" ("id" integer primary key autoincrement not null, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" text not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime, "token_last_six" varchar);
CREATE TABLE "audit_logs" ("id" integer primary key autoincrement not null, "actor_id" integer, "action" varchar not null, "subject_type" varchar, "subject_id" varchar, "metadata" text not null default '{}', "ip_address" varchar, "created_at" datetime not null default CURRENT_TIMESTAMP, foreign key("actor_id") references "users"("id") on delete set null);
CREATE TABLE "idempotency_keys" ("id" integer primary key autoincrement not null, "user_id" integer, "key" varchar not null, "request_hash" varchar not null, "response_status" integer not null, "response_body" text not null, "expires_at" datetime not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "domains" ("id" integer primary key autoincrement not null, "name" varchar not null, "display_name" varchar not null, "lifecycle_state" varchar not null default 'pending_verification', "revision" integer not null default '1', "nameservers_verified_at" datetime, "nameservers_verified_by" integer, "disabled_at" datetime, "deprovision_after" datetime, "created_at" datetime, "updated_at" datetime, "proxy_settings" text, "active_edge_revision" integer, "deleted_at" datetime, "cache_settings" text, "cache_epoch" integer not null default '1', "cache_development_mode_until" datetime, "tls_mode" varchar not null default 'managed', "active_tls_certificate_id" varchar, "revision_changed_at" datetime, "security_settings" text, "security_state" varchar not null default 'normal', "security_state_changed_at" datetime, "waf_profile" varchar not null default 'off', "delegation_token" varchar, "delegation_nameservers" text, "claim_expires_at" datetime, foreign key("nameservers_verified_by") references "users"("id") on delete set null);
CREATE TABLE "domain_user" ("domain_id" integer not null, "user_id" integer not null, "created_at" datetime not null default CURRENT_TIMESTAMP, foreign key("domain_id") references "domains"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade, primary key ("domain_id", "user_id"));
CREATE TABLE "dns_records" ("id" integer primary key autoincrement not null, "domain_id" integer not null, "type" varchar not null, "name" varchar not null, "content" text not null, "content_hash" varchar not null, "ttl" integer not null, "priority" integer not null default '0', "weight" integer not null default '0', "port" integer not null default '0', "mode" varchar not null default 'dns_only', "created_at" datetime, "updated_at" datetime, "geo_config" text, "origin" text, "origin_health" text, foreign key("domain_id") references "domains"("id") on delete cascade);
CREATE TABLE "dns_clusters" ("id" integer primary key autoincrement not null, "name" varchar not null, "location" varchar not null, "enabled" tinyint(1) not null default '1', "api_url" varchar not null, "api_key" text not null, "server_id" varchar not null default 'localhost', "nameservers" text not null default '[]', "capacity_zones" integer not null default '100000', "operational_notes" text, "last_health_status" varchar, "last_health_error" text, "last_health_at" datetime, "last_reconciled_revision" integer not null default '0', "created_at" datetime, "updated_at" datetime, "transfer_endpoint" varchar, "transfer_tsig_secret" text);
CREATE TABLE "edge_pools" ("id" integer primary key autoincrement not null, "name" varchar not null, "kind" varchar not null default 'shared', "enabled" tinyint(1) not null default '1', "revision" integer not null default '1', "created_at" datetime, "updated_at" datetime, "withdrawn" tinyint(1) not null default '0', "minimum_ready_cells" integer not null default '1', "replicas_per_edge" integer not null default '1', "maximum_domains_per_cell" integer not null default '20000', "routing_mode" varchar not null default 'geo_unicast', "anycast_ipv4" varchar, "anycast_ipv6" varchar, "cache_profile" varchar not null default 'standard', "compression_profile" varchar not null default 'standard', "waf_capable" tinyint(1) not null default '0', "waf_runtime_version" varchar, "waf_canary_state" varchar not null default 'not_required', "dns_fail_static" tinyint(1) not null default '0');
CREATE TABLE "domain_edge_placements" ("id" integer primary key autoincrement not null, "domain_id" integer not null, "active_pool_id" integer, "target_pool_id" integer, "state" varchar not null default 'pending', "desired_revision" integer not null, "drain_after" datetime, "last_error" text, "created_at" datetime, "updated_at" datetime, foreign key("domain_id") references "domains"("id") on delete cascade, foreign key("active_pool_id") references "edge_pools"("id") on delete restrict, foreign key("target_pool_id") references "edge_pools"("id") on delete restrict);
CREATE TABLE "edge_revisions" ("id" integer primary key autoincrement not null, "domain_id" integer not null, "revision" integer not null, "snapshot" text not null, "checksum" varchar not null, "status" varchar not null default 'validated', "created_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("domain_id") references "domains"("id") on delete cascade, foreign key("created_by") references "users"("id") on delete set null);
CREATE TABLE "edge_artifacts" ("sequence" integer primary key autoincrement not null, "edge_id" varchar not null, "domain_id" integer, "kind" varchar not null, "revision" integer not null, "payload" text not null, "checksum" varchar not null, "signature" varchar not null, "schema_version" integer not null default '1', "minimum_agent_version" varchar not null default '1.0.0', "maximum_agent_version" varchar not null default '1.99.99', "created_at" datetime, "updated_at" datetime, foreign key("edge_id") references "edges"("id") on delete cascade, foreign key("domain_id") references "domains"("id") on delete cascade);
CREATE TABLE "domain_name_tombstones" ("id" integer primary key autoincrement not null, "name" varchar not null, "source_domain_id" integer not null, "deprovisioned_at" datetime not null, "reclaim_after" datetime not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "system_settings" ("group" varchar not null, "values" text not null, "revision" integer not null default '1', "created_at" datetime, "updated_at" datetime, primary key ("group"));
CREATE TABLE "tls_certificates" ("id" varchar not null, "domain_id" integer not null, "kind" varchar not null, "status" varchar not null default 'pending', "certificate_pem" text not null, "chain_pem" text not null, "private_key_ciphertext" text not null, "names" text not null, "fingerprint_sha256" varchar not null, "not_before" datetime not null, "expires_at" datetime not null, "activated_at" datetime, "last_failure_at" datetime, "last_error" text, "created_at" datetime, "updated_at" datetime, "alerted_at" datetime, foreign key("domain_id") references "domains"("id") on delete cascade, primary key ("id"));
CREATE TABLE "acme_challenges" ("id" varchar not null, "tls_order_id" varchar not null, "hostname" varchar not null, "record_name" varchar not null, "record_value" text not null, "status" varchar not null default 'pending', "expires_at" datetime not null, "cleaned_at" datetime, "created_at" datetime, "updated_at" datetime, "authorization_url" varchar, "challenge_url" varchar, "token" varchar, foreign key("tls_order_id") references "tls_orders"("id") on delete cascade, primary key ("id"));
CREATE TABLE "acme_accounts" ("id" integer primary key autoincrement not null, "directory_url" varchar not null, "contact_email" varchar not null, "private_key_ciphertext" text not null, "account_url" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "notifications" ("id" varchar not null, "type" varchar not null, "notifiable_type" varchar not null, "notifiable_id" integer not null, "data" text not null, "read_at" datetime, "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE "usage_rollups" ("id" integer primary key autoincrement not null, "domain_id" integer not null, "interval_start" datetime not null, "interval_end" datetime not null, "granularity" varchar not null default 'hour', "requests" integer not null default '0', "bytes_in" integer not null default '0', "bytes_out" integer not null default '0', "cache_hits" integer not null default '0', "dns_queries" integer not null default '0', "status" varchar not null default 'finalized', "source_finalized_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("domain_id") references "domains"("id") on delete cascade);
CREATE TABLE "security_rules" ("id" integer primary key autoincrement not null, "domain_id" integer not null, "match_type" varchar not null, "value" varchar not null, "action" varchar not null, "priority" integer not null, "enabled" tinyint(1) not null default '1', "note" varchar, "created_at" datetime, "updated_at" datetime, foreign key("domain_id") references "domains"("id") on delete cascade);
CREATE TABLE "security_events" ("id" integer primary key autoincrement not null, "domain_id" integer not null, "edge_id" varchar, "hostname" varchar, "state" varchar, "reason_code" varchar not null, "details" text, "occurred_at" datetime not null, "created_at" datetime, "updated_at" datetime, foreign key("domain_id") references "domains"("id") on delete cascade, foreign key("edge_id") references "edges"("id") on delete set null);
CREATE TABLE "emergency_modes" ("id" varchar not null, "target_type" varchar not null, "target_id" varchar not null, "actions" text not null, "revision" integer not null default '1', "active" tinyint(1) not null default '1', "expires_at" datetime, "deactivated_at" datetime, "created_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("created_by") references "users"("id") on delete set null, primary key ("id"));
CREATE TABLE "backups" ("id" varchar not null, "requested_by" integer, "status" varchar not null default 'pending', "snapshot_id" varchar, "size_bytes" integer, "manifest_sha256" varchar, "last_error" text, "verified_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("requested_by") references "users"("id") on delete set null, primary key ("id"));
CREATE TABLE "edge_cells" ("id" integer primary key autoincrement not null, "edge_id" varchar not null, "edge_pool_id" integer, "name" varchar not null, "drained" tinyint(1) not null default ('0'), "status" varchar not null default ('pending'), "capacity" text, "created_at" datetime, "updated_at" datetime, "slot" integer not null, "http_port" integer, "https_port" integer, "status_port" integer, "runtime_path" varchar, "cache_path" varchar, "temporary_path" varchar, "resource_limits" text, foreign key("edge_id") references "edges"("id") on delete cascade on update no action, foreign key("edge_pool_id") references "edge_pools"("id") on delete restrict on update no action);
CREATE TABLE "domain_edge_cells" ("id" integer primary key autoincrement not null, "domain_id" integer not null, "edge_id" varchar not null, "replica" integer not null default '1', "active_cell_id" integer, "target_cell_id" integer, "desired_revision" integer not null, "state" varchar not null default 'deploying', "drain_after" datetime, "last_error" text, "created_at" datetime, "updated_at" datetime, foreign key("domain_id") references "domains"("id") on delete cascade, foreign key("edge_id") references "edges"("id") on delete cascade, foreign key("active_cell_id") references "edge_cells"("id") on delete restrict, foreign key("target_cell_id") references "edge_cells"("id") on delete restrict);
CREATE TABLE "edge_pool_endpoints" ("id" integer primary key autoincrement not null, "edge_id" varchar not null, "edge_pool_id" integer not null, "ipv4" varchar, "ipv6" varchar, "withdrawn" tinyint(1) not null default '0', "revision" integer not null default '1', "gateway_state" varchar not null default 'pending', "gateway_revision" integer not null default '0', "readiness_reason" varchar not null default 'gateway_not_acknowledged', "gateway_acknowledged_at" datetime, "created_at" datetime, "updated_at" datetime, "dns_published" tinyint(1) not null default '0', "dns_reason" varchar, "dns_state_changed_at" datetime, foreign key("edge_id") references "edges"("id") on delete cascade, foreign key("edge_pool_id") references "edge_pools"("id") on delete cascade);
CREATE TABLE "edges" ("id" varchar not null, "name" varchar not null, "country_code" varchar not null, "continent_code" varchar not null, "enabled" tinyint(1) not null default ('1'), "drained" tinyint(1) not null default ('0'), "bootstrap_token_hash" varchar, "identity_hash" varchar, "identity_revoked_at" datetime, "registered_at" datetime, "last_heartbeat_at" datetime, "agent_version" varchar, "capacity" text, "active_sequence" integer not null default ('0'), "created_at" datetime, "updated_at" datetime, "identity_certificate_serial" varchar, "identity_certificate_expires_at" datetime, "identity_csr_hash" varchar, "identity_certificate" text, "bootstrap_consumed_at" datetime, "cell_slot_count" integer not null default ('8'), "runtime_versions" text, "desired_runtime_versions" text, "runtime_versions_reported_at" datetime, "pending_identity_certificate" text, "pending_identity_certificate_serial" varchar, "pending_identity_certificate_expires_at" datetime, "pending_identity_csr_hash" varchar, "reported_identity_expires_at" datetime, "bootstrap_expires_at" datetime, primary key ("id"));
CREATE TABLE "waf_exclusions" ("id" integer primary key autoincrement not null, "domain_id" integer not null, "dimension" varchar not null, "value" varchar not null, "rule_id" integer, "reason" varchar not null, "owner_id" integer not null, "expires_at" datetime not null, "created_at" datetime, "updated_at" datetime, foreign key("domain_id") references "domains"("id") on delete cascade, foreign key("owner_id") references "users"("id") on delete restrict);
CREATE TABLE "fleet_releases" ("id" integer primary key autoincrement not null, "name" varchar not null, "gateway_image" varchar not null, "agent_image" varchar not null, "normal_cell_image" varchar not null, "waf_cell_image" varchar not null, "minimum_compatible_version" varchar not null, "maximum_compatible_version" varchar not null, "enabled" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "fleet_rollout_edges" ("id" integer primary key autoincrement not null, "fleet_rollout_id" varchar not null, "edge_id" varchar not null, "wave" integer not null, "status" varchar not null default 'pending', "previous_versions" text, "desired_versions" text not null, "failure_reason" varchar, "started_at" datetime, "finished_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("fleet_rollout_id") references "fleet_rollouts"("id") on delete cascade, foreign key("edge_id") references "edges"("id") on delete cascade);
CREATE TABLE "edge_tasks" ("id" varchar not null, "edge_id" varchar not null, "type" varchar not null, "payload" text not null, "status" varchar not null default ('pending'), "result" text, "finished_at" datetime, "created_at" datetime, "updated_at" datetime, "cache_purge_id" varchar, "attempts" integer not null default '0', "available_at" datetime, "last_error" varchar, foreign key("cache_purge_id") references "cache_purges"("id") on delete cascade on update no action, foreign key("edge_id") references "edges"("id") on delete cascade on update no action, primary key ("id"));
CREATE TABLE "tls_orders" ("id" varchar not null, "domain_id" integer not null, "certificate_id" varchar, "status" varchar not null default ('pending'), "names" text not null, "acme_order_url" varchar, "attempts" integer not null default '0', "available_at" datetime, "started_at" datetime, "finished_at" datetime, "last_error" text, "created_at" datetime, "updated_at" datetime, "acme_account_id" integer, "authorization_urls" text, "finalize_url" varchar, "certificate_url" varchar, "private_key_ciphertext" text, "csr_der" text, "dns_revision" integer, "next_poll_at" datetime, "alerted_at" datetime, "names_hash" varchar, foreign key("acme_account_id") references "acme_accounts"("id") on delete set null on update no action, foreign key("domain_id") references "domains"("id") on delete cascade on update no action, foreign key("certificate_id") references "tls_certificates"("id") on delete set null on update no action, primary key ("id"));
CREATE TABLE "dns_deployments" ("id" integer primary key autoincrement not null, "domain_id" integer not null, "dns_cluster_id" integer not null, "desired_revision" integer not null default ('0'), "deployed_revision" integer not null default ('0'), "status" varchar not null default ('pending'), "active_checksum" varchar, "active_rrsets" text not null default ('[]'), "last_error" text, "attempts" integer not null default '0', "last_attempted_at" datetime, "deployed_at" datetime, "created_at" datetime, "updated_at" datetime, "tombstone" tinyint(1) not null default ('0'), "deprovisioned_at" datetime, "verified_at" datetime, foreign key("dns_cluster_id") references "dns_clusters"("id") on delete cascade on update no action, foreign key("domain_id") references "domains"("id") on delete cascade on update no action);
CREATE TABLE "platform_dns_deployments" ("id" integer primary key autoincrement not null, "dns_cluster_id" integer not null, "desired_revision" integer not null default ('0'), "deployed_revision" integer not null default ('0'), "status" varchar not null default ('pending'), "active_checksum" varchar, "active_rrsets" text not null default ('[]'), "last_error" text, "attempts" integer not null default '0', "last_attempted_at" datetime, "deployed_at" datetime, "created_at" datetime, "updated_at" datetime, "active_zone" varchar, foreign key("dns_cluster_id") references "dns_clusters"("id") on delete cascade on update no action);
CREATE TABLE "edge_probe_results" ("id" integer primary key autoincrement not null, "observer_edge_id" varchar not null, "target_edge_id" varchar not null, "address" varchar not null, "ok" tinyint(1) not null, "detail" varchar, "checked_at" datetime not null, foreign key("observer_edge_id") references "edges"("id") on delete cascade, foreign key("target_edge_id") references "edges"("id") on delete cascade);
CREATE TABLE "operations" ("id" varchar not null, "actor_id" integer, "type" varchar not null, "status" varchar not null default ('pending'), "input" text not null default ('{}'), "result" text, "error" text, "attempts" integer not null default ('0'), "created_at" datetime, "updated_at" datetime, "started_at" datetime, "finished_at" datetime, "domain_id" integer, foreign key("actor_id") references "users"("id") on delete set null on update no action, foreign key("domain_id") references "domains"("id") on delete set null, primary key ("id"));
CREATE TABLE "cache_purges" ("id" varchar not null, "domain_id" integer not null, "requested_by" integer, "type" varchar not null, "cache_epoch" integer not null, "cache_keys" text, "status" varchar not null default ('pending'), "created_at" datetime, "updated_at" datetime, "sequence" integer, "operation_id" varchar, foreign key("requested_by") references "users"("id") on delete set null on update no action, foreign key("domain_id") references "domains"("id") on delete cascade on update no action, foreign key("operation_id") references "operations"("id") on delete set null, primary key ("id"));
CREATE TABLE "fleet_rollouts" ("id" varchar not null, "fleet_release_id" integer not null, "previous_release_id" integer, "created_by" integer, "status" varchar not null default ('pending'), "current_wave" integer not null default ('0'), "maximum_parallel" integer not null default ('2'), "minimum_ready_percent" integer not null default ('100'), "maximum_error_percent" integer not null default ('5'), "mixed_version_window_minutes" integer not null default ('60'), "pause_reason" varchar, "started_at" datetime, "finished_at" datetime, "created_at" datetime, "updated_at" datetime, "operation_id" varchar, foreign key("created_by") references "users"("id") on delete set null on update no action, foreign key("previous_release_id") references "fleet_releases"("id") on delete restrict on update no action, foreign key("fleet_release_id") references "fleet_releases"("id") on delete restrict on update no action, foreign key("operation_id") references "operations"("id") on delete set null, primary key ("id"));
CREATE TABLE "dns_zone_changes" ("id" integer primary key autoincrement not null, "zone" varchar not null, "serial" integer not null default '0', "deleted" tinyint(1) not null default '0', "created_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE "personal_access_token_domains" ("personal_access_token_id" integer not null, "domain_id" integer not null, foreign key("personal_access_token_id") references "personal_access_tokens"("id") on delete cascade, foreign key("domain_id") references "domains"("id") on delete cascade, primary key ("personal_access_token_id", "domain_id"));
CREATE TABLE "nameserver_address_probes" ("id" integer primary key autoincrement not null, "address" varchar not null, "zone" varchar not null, "status" varchar not null default 'pending', "requested_at" datetime not null, "answered_at" datetime, "observer_edge_id" varchar, "last_error" varchar, "created_at" datetime, "updated_at" datetime, foreign key("observer_edge_id") references "edges"("id") on delete set null);
CREATE TABLE "control_plane_state" ("id" integer not null, "epoch" integer not null default '1', "active_node" varchar, "addresses" text not null, "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE "control_nodes" ("id" integer primary key autoincrement not null, "name" varchar not null, "role" varchar not null, "address" varchar not null, "fingerprints" text, "replication_lag_seconds" integer, "valkey_linked" tinyint(1), "reported_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "platform_dns_settings" ("id" integer primary key autoincrement not null, "platform_domain" varchar not null, "proxy_hostname" varchar not null, "nameservers" text not null, "soa_primary" varchar not null, "soa_mailbox" varchar not null, "soa_refresh" integer not null, "soa_retry" integer not null, "soa_expire" integer not null, "soa_minimum_ttl" integer not null, "default_ttl" integer not null, "created_at" datetime, "updated_at" datetime, "revision" integer not null default ('1'), "soa_serial" integer not null default ('0'), "zone_content_checksum" varchar, "customer_nameserver_pairs" text, "cluster_targets" text default '[]');
CREATE TABLE "generated_reports" ("id" varchar not null, "kind" varchar not null, "period" varchar not null, "format" varchar not null, "path" varchar not null, "size_bytes" integer not null, "checksum_sha256" varchar not null, "created_at" datetime not null default CURRENT_TIMESTAMP, primary key ("id"));
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE INDEX "personal_access_tokens_tokenable_type_tokenable_id_index" on "personal_access_tokens" ("tokenable_type", "tokenable_id");
CREATE UNIQUE INDEX "personal_access_tokens_token_unique" on "personal_access_tokens" ("token");
CREATE INDEX "personal_access_tokens_expires_at_index" on "personal_access_tokens" ("expires_at");
CREATE INDEX "users_type_id_index" on "users" ("type", "id");
CREATE INDEX "audit_logs_subject_type_subject_id_index" on "audit_logs" ("subject_type", "subject_id");
CREATE INDEX "audit_logs_action_id_index" on "audit_logs" ("action", "id");
CREATE UNIQUE INDEX "idempotency_keys_user_id_key_unique" on "idempotency_keys" ("user_id", "key");
CREATE INDEX "idempotency_keys_expires_at_index" on "idempotency_keys" ("expires_at");
CREATE INDEX "domains_lifecycle_state_id_index" on "domains" ("lifecycle_state", "id");
CREATE INDEX "domain_user_user_id_domain_id_index" on "domain_user" ("user_id", "domain_id");
CREATE UNIQUE INDEX "dns_records_logical_unique" on "dns_records" ("domain_id", "name", "type", "content_hash", "priority", "weight", "port");
CREATE INDEX "dns_records_domain_id_name_type_id_index" on "dns_records" ("domain_id", "name", "type", "id");
CREATE INDEX "dns_clusters_enabled_id_index" on "dns_clusters" ("enabled", "id");
CREATE UNIQUE INDEX "dns_clusters_name_unique" on "dns_clusters" ("name");
CREATE UNIQUE INDEX "edge_pools_name_unique" on "edge_pools" ("name");
CREATE UNIQUE INDEX "domain_edge_placements_domain_id_unique" on "domain_edge_placements" ("domain_id");
CREATE UNIQUE INDEX "edge_revisions_domain_id_revision_unique" on "edge_revisions" ("domain_id", "revision");
CREATE INDEX "edge_artifacts_edge_id_sequence_index" on "edge_artifacts" ("edge_id", "sequence");
CREATE UNIQUE INDEX "edge_artifacts_content_unique" on "edge_artifacts" ("edge_id", "domain_id", "revision", "kind", "checksum");
